import React from 'react';
import { 
  LayoutDashboard, 
  PenTool, 
  Settings, 
  Activity, 
  LogOut, 
  Bell,
  Menu,
  X
} from 'lucide-react';
import { User } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  user: User;
  activeTab: string;
  onTabChange: (tab: string) => void;
}

