import React from 'react';
import { Draft } from '../types';
import { 
  Calendar, 
  Send, 
  Edit3, 
  Trash2, 
  CheckCircle, 
  Clock, 
  AlertCircle,
  ThumbsUp,
  Github
} from 'lucide-react';

interface DraftCardProps {
  draft: Draft;
  onStatusChange: (id: string, status: Draft['status']) => void;
  onDelete: (id: string) => void;
}

const DraftCard: React.FC<DraftCardProps> = ({ draft, onStatusChange, onDelete }) => {
  const getStatusColor = (status: Draft['status']) => {
    switch (status) {
      case 'approved': return 'bg-green-100 text-green-700 border-green-200';
      case 'published': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'scheduled': return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'draft': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'failed': return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getStatusIcon = (status: Draft['status']) => {
    switch (status) {
      case 'approved': return <CheckCircle className="w-4 h-4" />;
      case 'published': return <Send className="w-4 h-4" />;
      case 'scheduled': return <Clock className="w-4 h-4" />;
      case 'failed': return <AlertCircle className="w-4 h-4" />;
      default: return <Edit3 className="w-4 h-4" />;
    }
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow duration-200 flex flex-col h-full">
      <div className="p-5 flex-1">
        <div className="flex justify-between items-start mb-3">
          <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold border ${getStatusColor(draft.status)}`}>
            {getStatusIcon(draft.status)}
            <span className="capitalize">{draft.status}</span>
          </div>
          <div className="flex items-center gap-1 text-xs text-slate-500">
            <span className="font-medium">{Math.round(draft.confidence_score * 100)}%</span>
            <span>AI score</span>
          </div>
        </div>

        {draft.activity_summary && (
          <div className="flex items-center gap-2 mb-3 text-xs text-slate-500 bg-slate-50 p-2 rounded border border-slate-100">
            <Github className="w-3.5 h-3.5" />
            <span className="truncate">{draft.activity_summary}</span>
          </div>
        )}

        <p className="text-slate-800 text-sm leading-relaxed whitespace-pre-wrap font-medium">
          {draft.content}
        </p>
      </div>

      <div className="border-t border-slate-100 p-3 bg-slate-50/50 rounded-b-xl flex justify-between items-center">
        <div className="flex gap-2">
          {draft.status === 'draft' && (
            <>
              <button 
                onClick={() => onStatusChange(draft.id, 'approved')}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 text-white text-xs font-medium rounded hover:bg-green-700 transition-colors"
              >
                <ThumbsUp className="w-3.5 h-3.5" />
                Approve
              </button>
              <button 
                onClick={() => onDelete(draft.id)}
                className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded transition-colors"
                title="Reject"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </>
          )}

          {draft.status === 'approved' && (
            <>
              <button 
                onClick={() => onStatusChange(draft.id, 'published')}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white text-xs font-medium rounded hover:bg-blue-700 transition-colors"
              >
                <Send className="w-3.5 h-3.5" />
                Publish Now
              </button>
              <button 
                onClick={() => onStatusChange(draft.id, 'scheduled')}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-slate-300 text-slate-700 text-xs font-medium rounded hover:bg-slate-50 transition-colors"
              >
                <Calendar className="w-3.5 h-3.5" />
                Schedule
              </button>
            </>
          )}

          {draft.status === 'scheduled' && (
             <div className="text-xs text-purple-600 font-medium flex items-center gap-1">
               <Clock className="w-3.5 h-3.5" />
               Runs in ~15m
             </div>
          )}

           {draft.status === 'published' && (
             <div className="text-xs text-blue-600 font-medium flex items-center gap-1">
               <Send className="w-3.5 h-3.5" />
               Live on LinkedIn
             </div>
          )}
        </div>

        {draft.status === 'draft' && (
           <button className="text-xs text-slate-400 hover:text-blue-600 flex items-center gap-1">
             <Edit3 className="w-3.5 h-3.5" />
             Edit
           </button>
        )}
      </div>
    </div>
  );
};

export default DraftCard;

import React, { useState } from 'react';
import { Draft } from '../types';
import DraftCard from './DraftCard';
import { Filter, Plus } from 'lucide-react';

interface DraftsViewProps {
  drafts: Draft[];
  setDrafts: React.Dispatch<React.SetStateAction<Draft[]>>;
}

const DraftsView: React.FC<DraftsViewProps> = ({ drafts, setDrafts }) => {
  const [filter, setFilter] = useState<'all' | 'draft' | 'approved' | 'scheduled' | 'published'>('all');

  const handleStatusChange = (id: string, newStatus: Draft['status']) => {
    setDrafts(prev => prev.map(d => 
      d.id === id ? { ...d, status: newStatus } : d
    ));
  };

  const handleDelete = (id: string) => {
    setDrafts(prev => prev.filter(d => d.id !== id));
  };

  const filteredDrafts = filter === 'all' 
    ? drafts 
    : drafts.filter(d => d.status === filter);

  // Group stats
  const stats = {
    draft: drafts.filter(d => d.status === 'draft').length,
    approved: drafts.filter(d => d.status === 'approved').length,
    scheduled: drafts.filter(d => d.status === 'scheduled').length,
    published: drafts.filter(d => d.status === 'published').length
  };

  return (
    <div className="space-y-6">
      {/* Filters and Stats */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex p-1 bg-white border border-slate-200 rounded-lg">
          {(['all', 'draft', 'approved', 'scheduled', 'published'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${
                filter === f 
                  ? 'bg-slate-900 text-white shadow-sm' 
                  : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
              }`}
            >
              <span className="capitalize">{f}</span>
              {f !== 'all' && (
                <span className={`ml-2 text-xs py-0.5 px-1.5 rounded-full ${
                  filter === f ? 'bg-slate-700 text-white' : 'bg-slate-100 text-slate-500'
                }`}>
                  {stats[f as keyof typeof stats] || 0}
                </span>
              )}
            </button>
          ))}
        </div>

        <button className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-medium transition-colors shadow-sm shadow-blue-200">
          <Plus className="w-4 h-4" />
          New Draft
        </button>
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-3 gap-6">
        {filteredDrafts.length > 0 ? (
          filteredDrafts.map(draft => (
            <DraftCard 
              key={draft.id} 
              draft={draft} 
              onStatusChange={handleStatusChange}
              onDelete={handleDelete}
            />
          ))
        ) : (
          <div className="col-span-full py-20 text-center bg-white rounded-xl border border-slate-200 border-dashed">
            <div className="mx-auto w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center mb-4 text-slate-400">
              <Filter className="w-6 h-6" />
            </div>
            <h3 className="text-lg font-medium text-slate-900">No drafts found</h3>
            <p className="text-slate-500 max-w-sm mx-auto mt-2">
              There are no drafts matching the current filter. Wait for the AI to generate new content from your activity.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default DraftsView;

