import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import DraftsView from './components/DraftsView';
import Settings from './components/Settings';
import ActivityFeed from './components/ActivityFeed';
import { 
  CURRENT_USER, 
  INITIAL_DRAFTS, 
  INITIAL_SOURCES, 
  INITIAL_ACTIVITIES 
} from './constants';
import { Draft, Source } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [drafts, setDrafts] = useState<Draft[]>(INITIAL_DRAFTS);
  const [sources, setSources] = useState<Source[]>(INITIAL_SOURCES);

  // Simulate polling for draft updates (e.g. status changes from cron jobs)
  useEffect(() => {
    const interval = setInterval(() => {
      // Logic to check if scheduled posts should "publish" based on time
      setDrafts(prev => prev.map(d => {
        if (d.status === 'scheduled' && d.scheduled_for && new Date(d.scheduled_for) <= new Date()) {
          return { ...d, status: 'published', published_at: new Date().toISOString() };
        }
        return d;
      }));
    }, 10000); // Check every 10s for demo purposes

    return () => clearInterval(interval);
  }, []);

  const handleToggleSource = (id: string) => {
    setSources(prev => prev.map(s => 
      s.id === id ? { ...s, status: s.status === 'connected' ? 'disconnected' : 'connected' } : s
    ));
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard drafts={drafts} sources={sources} activities={INITIAL_ACTIVITIES} />;
      case 'drafts':
        return <DraftsView drafts={drafts} setDrafts={setDrafts} />;
      case 'activity':
        return <ActivityFeed activities={INITIAL_ACTIVITIES} />;
      case 'settings':
        return <Settings user={CURRENT_USER} sources={sources} onToggleSource={handleToggleSource} />;
      default:
        return <Dashboard drafts={drafts} sources={sources} activities={INITIAL_ACTIVITIES} />;
    }
  };

  return (
    <Layout user={CURRENT_USER} activeTab={activeTab} onTabChange={setActiveTab}>
      <div className="max-w-7xl mx-auto">
        {renderContent()}
      </div>
    </Layout>
  );
};

export default App;

