import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import DraftsView from './components/DraftsView';
import Settings from './components/Settings';
import ActivityFeed from './components/ActivityFeed';
import { 
  CURRENT_USER, 
  INITIAL_DRAFTS, 
  INITIAL_SOURCES, 
  INITIAL_ACTIVITIES 
} from './constants';
import { Draft, Source, Activity } from './types';

// Storage keys
const STORAGE_KEYS = {
  DRAFTS: 'linkedqueue_drafts',
  SOURCES: 'linkedqueue_sources',
  ACTIVITIES: 'linkedqueue_activities'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // Initialize state from LocalStorage or constants
  const [drafts, setDrafts] = useState<Draft[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.DRAFTS);
    return saved ? JSON.parse(saved) : INITIAL_DRAFTS;
  });

  const [sources, setSources] = useState<Source[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.SOURCES);
    return saved ? JSON.parse(saved) : INITIAL_SOURCES;
  });

  const [activities, setActivities] = useState<Activity[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.ACTIVITIES);
    return saved ? JSON.parse(saved) : INITIAL_ACTIVITIES;
  });

  const [isGenerating, setIsGenerating] = useState(false);

  // Persist state changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.DRAFTS, JSON.stringify(drafts));
  }, [drafts]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.SOURCES, JSON.stringify(sources));
  }, [sources]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.ACTIVITIES, JSON.stringify(activities));
  }, [activities]);

  // Simulate polling for draft updates (e.g. status changes from cron jobs)
  useEffect(() => {
    const interval = setInterval(() => {
      setDrafts(prev => prev.map(d => {
        // Auto-publish if scheduled time has passed
        if (d.status === 'scheduled' && d.scheduled_for && new Date(d.scheduled_for) <= new Date()) {
          return { ...d, status: 'published', published_at: new Date().toISOString() };
        }
        return d;
      }));
    }, 10000); 

    return () => clearInterval(interval);
  }, []);

  const handleToggleSource = (id: string) => {
    setSources(prev => prev.map(s => 
      s.id === id ? { ...s, status: s.status === 'connected' ? 'disconnected' : 'connected' } : s
    ));
  };

  const handleGenerateDraft = async () => {
    setIsGenerating(true);
    try {
      // Initialize Gemini Client
      // Note: In a real production app, you might proxy this through a backend to keep keys secure,
      // but for this client-side demo we use the env variable directly if available.
      const apiKey = process.env.API_KEY || '';

      let content = "";
      let confidence = 0.85;

      if (apiKey) {
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: `Generate a professional and engaging LinkedIn post about building a SaaS product in public. 
                     The post should be insightful, use 1-2 emojis, and be under 300 characters. 
                     Focus on the topic of "Shipping consistently" or "Customer Feedback".`,
        });
        content = response.text || "Failed to generate content.";
        confidence = 0.95;
      } else {
        // Fallback simulation if no API key is present
        await new Promise(resolve => setTimeout(resolve, 1500));
        const topics = [
          "The importance of customer feedback loops in early stage SaaS. 🔄 #BuildingInPublic",
          "Shipping implies risk, but not shipping implies certainty of failure. 🚀 #StartupLife",
          "Just deployed a new feature based on user requests. It feels great to close that feedback loop! 💡 #Engineering"
        ];
        content = topics[Math.floor(Math.random() * topics.length)];
      }

      const newDraft: Draft = {
        id: `d-${Date.now()}`,
        content: content.trim(),
        status: 'draft',
        style: 'humble_builder',
        confidence_score: confidence,
        created_at: new Date().toISOString(),
        activity_summary: "Manual AI Generation"
      };

      setDrafts(prev => [newDraft, ...prev]);
      // Switch to drafts tab to see the result
      setActiveTab('drafts');
    } catch (error) {
      console.error("Generation failed", error);
      alert("Failed to generate draft. Please check your API configuration.");
    } finally {
      setIsGenerating(false);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard drafts={drafts} sources={sources} activities={activities} />;
      case 'drafts':
        return (
          <DraftsView 
            drafts={drafts} 
            setDrafts={setDrafts} 
            onGenerate={handleGenerateDraft}
            isGenerating={isGenerating}
          />
        );
      case 'activity':
        return <ActivityFeed activities={activities} />;
      case 'settings':
        return <Settings user={CURRENT_USER} sources={sources} onToggleSource={handleToggleSource} />;
      default:
        return <Dashboard drafts={drafts} sources={sources} activities={activities} />;
    }
  };

  return (
    <Layout user={CURRENT_USER} activeTab={activeTab} onTabChange={setActiveTab}>
      <div className="max-w-7xl mx-auto">
        {renderContent()}
      </div>
    </Layout>
  );
};

export default App;

