  isOpen: boolean;
  onClose: () => void;
  onSchedule: (date: Date) => void;
}

const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

const DAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

const ScheduleModal: React.FC<ScheduleModalProps> = ({ isOpen, onClose, onSchedule }) => {
  const [currentDate, setCurrentDate] = useState(new Date()); // For navigation
  const [selectedDate, setSelectedDate] = useState(new Date()); // For selection
  const [time, setTime] = useState("09:00");

  useEffect(() => {
    if (isOpen) {
      // Reset to current time/date when opening
      const now = new Date();
      setCurrentDate(now);
      setSelectedDate(now);

      // Default to next hour
      const nextHour = new Date(now);
      nextHour.setHours(nextHour.getHours() + 1);
      nextHour.setMinutes(0);

      const hours = String(nextHour.getHours()).padStart(2, '0');
      const minutes = String(nextHour.getMinutes()).padStart(2, '0');
      setTime(`${hours}:${minutes}`);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const getDaysInMonth = (year: number, month: number) => {
    return new Date(year, month + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (year: number, month: number) => {
    return new Date(year, month, 1).getDay();
  };

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());

  const days = [];
  for (let i = 0; i < firstDay; i++) {
    days.push(null);
  }
  for (let i = 1; i <= daysInMonth; i++) {
    days.push(i);
  }

  const handlePrevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const handleDateClick = (day: number) => {
    const newDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
    setSelectedDate(newDate);
  };

  const isSelected = (day: number) => {
    return selectedDate.getDate() === day &&
           selectedDate.getMonth() === currentDate.getMonth() &&
           selectedDate.getFullYear() === currentDate.getFullYear();
  };

  const isToday = (day: number) => {
    const today = new Date();
    return day === today.getDate() &&
           currentDate.getMonth() === today.getMonth() &&
           currentDate.getFullYear() === today.getFullYear();
  };

  const handleConfirm = () => {
    const [hours, minutes] = time.split(':').map(Number);
    const finalDate = new Date(selectedDate);
    finalDate.setHours(hours);
    finalDate.setMinutes(minutes);
    onSchedule(finalDate);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden animate-in zoom-in-95 duration-200 border border-slate-200">
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
          <h3 className="font-semibold text-slate-900 flex items-center gap-2">
            <CalendarIcon className="w-5 h-5 text-blue-600" />
            Schedule Post
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-1 rounded-full hover:bg-slate-100 transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-5">
          {/* Calendar Header */}
          <div className="flex justify-between items-center mb-4">
            <h4 className="font-semibold text-slate-900 text-sm">
              {MONTH_NAMES[currentDate.getMonth()]} {currentDate.getFullYear()}
            </h4>
            <div className="flex gap-1">
              <button onClick={handlePrevMonth} className="p-1.5 hover:bg-slate-100 rounded-md text-slate-500 hover:text-slate-900 transition-colors">
                <ChevronLeft className="w-4 h-4" />
              </button>
              <button onClick={handleNextMonth} className="p-1.5 hover:bg-slate-100 rounded-md text-slate-500 hover:text-slate-900 transition-colors">
                <ChevronRight className="w-4 h-4" />
              </button>
            </div>
          </div>

          {/* Calendar Grid */}
          <div className="grid grid-cols-7 gap-1 mb-5">
            {DAYS.map(day => (
              <div key={day} className="text-center text-[10px] font-bold text-slate-400 py-1 uppercase tracking-wide">
                {day}
              </div>
            ))}
            {days.map((day, index) => (
              <div key={index} className="aspect-square">
                {day !== null ? (
                  <button
                    onClick={() => handleDateClick(day)}
                    className={`w-full h-full rounded-md text-sm flex items-center justify-center transition-all duration-200
                      ${isSelected(day) 
                        ? 'bg-blue-600 text-white shadow-md shadow-blue-200 font-semibold transform scale-105' 
                        : isToday(day)
                          ? 'bg-blue-50 text-blue-600 font-medium border border-blue-100'
                          : 'hover:bg-slate-50 text-slate-700 hover:scale-105'
                      }
                    `}
                  >
                    {day}
                  </button>
                ) : (
                  <div />
                )}
              </div>
            ))}
          </div>

          {/* Time Selection */}
          <div className="flex items-center gap-3 mb-6 p-3 bg-slate-50 rounded-lg border border-slate-100 hover:border-blue-200 transition-colors group">
            <Clock className="w-5 h-5 text-slate-400 group-hover:text-blue-500 transition-colors" />
            <div className="flex-1">
              <label className="text-xs font-semibold text-slate-500 block mb-1 uppercase tracking-wide">Time</label>
              <input 
                type="time" 
                value={time}
                onChange={(e) => setTime(e.target.value)}
                className="bg-transparent text-slate-900 font-bold focus:outline-none w-full cursor-pointer"
              />
            </div>
          </div>

          {/* Actions */}
          <div className="flex gap-3">
            <button 
              onClick={onClose}
              className="flex-1 px-4 py-2.5 border border-slate-200 text-slate-600 font-medium rounded-lg hover:bg-slate-50 hover:text-slate-900 transition-colors text-sm"
            >
              Cancel
            </button>
            <button 
              onClick={handleConfirm}
              className="flex-1 px-4 py-2.5 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 transition-all shadow-sm shadow-blue-200 text-sm hover:shadow-md hover:translate-y-[-1px]"
            >
              Confirm Schedule
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ScheduleModal;

import React, { useState } from 'react';
import { Draft } from '../types';
import { 
  Calendar, 
  Send, 
  Edit3, 
  Trash2, 
  CheckCircle, 
  Clock, 
  AlertCircle,
  ThumbsUp,
  Github,
  RefreshCcw,
  Loader2,
  XCircle
} from 'lucide-react';

interface DraftCardProps {
  draft: Draft;
  onStatusChange: (id: string, status: Draft['status']) => void;
  onDelete: (id: string) => void;
}

const DraftCard: React.FC<DraftCardProps> = ({ draft, onStatusChange, onDelete }) => {
  const [isPublishing, setIsPublishing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const handlePublish = async () => {
    setIsPublishing(true);
    setErrorMessage(null);

    // Simulate network request
    await new Promise(resolve => setTimeout(resolve, 1500));

    // Simulate random failure (20% chance) to demonstrate retry logic
    const fail = Math.random() < 0.20;

    if (fail) {
      onStatusChange(draft.id, 'failed');
      setErrorMessage("Network timeout. Connection to LinkedIn API failed.");
    } else {
      onStatusChange(draft.id, 'published');
      setErrorMessage(null);
    }
    setIsPublishing(false);
  };

  const getStatusColor = (status: Draft['status']) => {
    switch (status) {
      case 'approved': return 'bg-green-100 text-green-700 border-green-200';
      case 'published': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'scheduled': return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'draft': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'failed': return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getStatusIcon = (status: Draft['status']) => {
    switch (status) {
      case 'approved': return <CheckCircle className="w-4 h-4" />;
      case 'published': return <Send className="w-4 h-4" />;
      case 'scheduled': return <Clock className="w-4 h-4" />;
      case 'failed': return <AlertCircle className="w-4 h-4" />;
      default: return <Edit3 className="w-4 h-4" />;
    }
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow duration-200 flex flex-col h-full group">
      <div className="p-5 flex-1 relative">
        <div className="flex justify-between items-start mb-3">
          <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold border ${getStatusColor(draft.status)}`}>
            {getStatusIcon(draft.status)}
            <span className="capitalize">{draft.status}</span>
          </div>
          <div className="flex items-center gap-1 text-xs text-slate-500">
            <span className="font-medium">{Math.round(draft.confidence_score * 100)}%</span>
            <span>AI score</span>
          </div>
        </div>

        {draft.activity_summary && (
          <div className="flex items-center gap-2 mb-3 text-xs text-slate-500 bg-slate-50 p-2 rounded border border-slate-100">
            <Github className="w-3.5 h-3.5" />
            <span className="truncate">{draft.activity_summary}</span>
          </div>
        )}

        <p className="text-slate-800 text-sm leading-relaxed whitespace-pre-wrap font-medium">
          {draft.content}
        </p>

        {errorMessage && draft.status === 'failed' && (
          <div className="mt-3 p-2 bg-red-50 border border-red-100 rounded text-xs text-red-600 flex items-start gap-2">
            <XCircle className="w-3.5 h-3.5 mt-0.5 flex-shrink-0" />
            <span>{errorMessage}</span>
          </div>
        )}
      </div>

      <div className="border-t border-slate-100 p-3 bg-slate-50/50 rounded-b-xl flex justify-between items-center">
        <div className="flex gap-2 w-full">
          {draft.status === 'draft' && (
            <>
              <button 
                onClick={() => onStatusChange(draft.id, 'approved')}
                className="flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 bg-green-600 text-white text-xs font-medium rounded hover:bg-green-700 transition-colors"
              >
                <ThumbsUp className="w-3.5 h-3.5" />
                Approve
              </button>
              <button 
                onClick={() => onDelete(draft.id)}
                className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded transition-colors"
                title="Reject"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </>
          )}

          {draft.status === 'approved' && (
            <>
              <button 
                onClick={handlePublish}
                disabled={isPublishing}
                className="flex items-center justify-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white text-xs font-medium rounded hover:bg-blue-700 transition-colors disabled:bg-blue-400 disabled:cursor-not-allowed min-w-[100px]"
              >
                {isPublishing ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    <span>Publishing...</span>
                  </>
                ) : (
                  <>
                    <Send className="w-3.5 h-3.5" />
                    <span>Publish Now</span>
                  </>
                )}
              </button>
              <button 
                onClick={() => onStatusChange(draft.id, 'scheduled')}
                disabled={isPublishing}
                className="flex items-center justify-center gap-1.5 px-3 py-1.5 bg-white border border-slate-300 text-slate-700 text-xs font-medium rounded hover:bg-slate-50 transition-colors"
              >
                <Calendar className="w-3.5 h-3.5" />
                Schedule
              </button>
            </>
          )}

          {draft.status === 'failed' && (
             <div className="flex items-center gap-2 w-full">
               <button 
                onClick={handlePublish}
                disabled={isPublishing}
                className="flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 bg-red-600 text-white border border-red-600 text-xs font-medium rounded hover:bg-red-700 transition-colors disabled:opacity-70 shadow-sm shadow-red-200"
              >
                {isPublishing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RefreshCcw className="w-3.5 h-3.5" />}
                Retry Publish
              </button>
              <button 
                onClick={() => onDelete(draft.id)}
                className="px-3 py-1.5 text-slate-600 hover:text-red-600 border border-slate-300 rounded hover:bg-slate-50 text-xs font-medium transition-colors"
              >
                Discard
              </button>
             </div>
          )}

          {draft.status === 'scheduled' && (
             <div className="text-xs text-purple-600 font-medium flex items-center gap-1 w-full justify-center bg-purple-50 py-1.5 rounded border border-purple-100">
               <Clock className="w-3.5 h-3.5" />
               Scheduled for {draft.scheduled_for ? new Date(draft.scheduled_for).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : 'Future'}
             </div>
          )}

           {draft.status === 'published' && (
             <div className="text-xs text-blue-600 font-medium flex items-center gap-1 w-full justify-center bg-blue-50 py-1.5 rounded border border-blue-100">
               <Send className="w-3.5 h-3.5" />
               Live on LinkedIn
             </div>
          )}
        </div>

        {draft.status === 'draft' && (
           <button className="text-xs text-slate-400 hover:text-blue-600 flex items-center gap-1 ml-2 opacity-0 group-hover:opacity-100 transition-opacity">
             <Edit3 className="w-3.5 h-3.5" />
           </button>
        )}
      </div>
    </div>
  );
};

export default DraftCard;

