    const randomFiller = new Date(date) < new Date(Date.now() - 86400000 * 2) && dayActivities === 0 ? Math.floor(Math.random() * 50) + 10 : 0;

    return {
        name: new Date(date).toLocaleDateString('en-US', { weekday: 'short' }),
