} from 'lucide-react';

interface DraftCardProps {
  draft: Draft;
  onStatusChange: (id: string, status: Draft['status']) => void;
  onDelete: (id: string) => void;
}

const DraftCard: React.FC<DraftCardProps> = ({ draft, onStatusChange, onDelete }) => {
  const [isPublishing, setIsPublishing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const handlePublish = async () => {
    setIsPublishing(true);
    setErrorMessage(null);

    // Simulate network request
    await new Promise(resolve => setTimeout(resolve, 1500));

    // Simulate random failure (20% chance) to demonstrate retry logic
    const fail = Math.random() < 0.20;

    if (fail) {
      onStatusChange(draft.id, 'failed');
      setErrorMessage("Network timeout. Connection to LinkedIn API failed.");
    } else {
      onStatusChange(draft.id, 'published');
      setErrorMessage(null);
    }
    setIsPublishing(false);
  };

  const getStatusColor = (status: Draft['status']) => {
    switch (status) {
      case 'approved': return 'bg-green-100 text-green-700 border-green-200';
      case 'published': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'scheduled': return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'draft': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'failed': return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getStatusIcon = (status: Draft['status']) => {
    switch (status) {
      case 'approved': return <CheckCircle className="w-4 h-4" />;
      case 'published': return <Send className="w-4 h-4" />;
      case 'scheduled': return <Clock className="w-4 h-4" />;
      case 'failed': return <AlertCircle className="w-4 h-4" />;
      default: return <Edit3 className="w-4 h-4" />;
    }
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow duration-200 flex flex-col h-full group">
      <div className="p-4 flex-1 relative">
        <div className="flex justify-between items-start mb-3">
          <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold border ${getStatusColor(draft.status)}`}>
            {getStatusIcon(draft.status)}
            <span className="capitalize">{draft.status}</span>
          </div>
          <div className="flex items-center gap-1 text-xs text-slate-500">
            <span className="font-medium">{Math.round(draft.confidence_score * 100)}%</span>
            <span>AI score</span>
          </div>
        </div>

        {draft.activity_summary && (
          <div className="flex items-center gap-2 mb-3 text-xs text-slate-500 bg-slate-50 p-2 rounded border border-slate-100">
            <Github className="w-3.5 h-3.5" />
            <span className="truncate">{draft.activity_summary}</span>
          </div>
        )}

        <p className="text-slate-800 text-sm leading-relaxed whitespace-pre-wrap font-medium">
          {draft.content}
        </p>

        {errorMessage && draft.status === 'failed' && (
          <div className="mt-3 p-2 bg-red-50 border border-red-100 rounded text-xs text-red-600 flex items-start gap-2">
            <XCircle className="w-3.5 h-3.5 mt-0.5 flex-shrink-0" />
            <span>{errorMessage}</span>
          </div>
        )}
      </div>

      <div className="border-t border-slate-100 p-3 bg-slate-50/50 rounded-b-xl flex justify-between items-center">
        <div className="flex gap-2 w-full">
          {draft.status === 'draft' && (
            <>
              <button 
                onClick={() => onStatusChange(draft.id, 'approved')}
                className="flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 bg-green-600 text-white text-xs font-medium rounded hover:bg-green-700 transition-colors"
              >
                <ThumbsUp className="w-3.5 h-3.5" />
                Approve
              </button>
              <button 
                onClick={() => onDelete(draft.id)}
                className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded transition-colors"
                title="Reject"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </>
          )}

          {draft.status === 'approved' && (
            <>
              <button 
                onClick={handlePublish}
                disabled={isPublishing}
                className="flex items-center justify-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white text-xs font-medium rounded hover:bg-blue-700 transition-colors disabled:bg-blue-400 disabled:cursor-not-allowed min-w-[100px]"
              >
                {isPublishing ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    <span>Publishing...</span>
                  </>
                ) : (
                  <>
                    <Send className="w-3.5 h-3.5" />
                    <span>Publish Now</span>
                  </>
                )}
              </button>
              <button 
                onClick={() => onStatusChange(draft.id, 'scheduled')}
                disabled={isPublishing}
                className="flex items-center justify-center gap-1.5 px-3 py-1.5 bg-white border border-slate-300 text-slate-700 text-xs font-medium rounded hover:bg-slate-50 transition-colors"
              >
                <Calendar className="w-3.5 h-3.5" />
                Schedule
              </button>
            </>
          )}

          {draft.status === 'failed' && (
             <div className="flex items-center gap-2 w-full">
               <button 
                onClick={handlePublish}
                disabled={isPublishing}
                className="flex-1 flex items-center justify-center gap-1.5 px-3 py-1.5 bg-red-600 text-white border border-red-600 text-xs font-medium rounded hover:bg-red-700 transition-colors disabled:opacity-70 shadow-sm shadow-red-200"
              >
                {isPublishing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <RefreshCcw className="w-3.5 h-3.5" />}
                Retry Publish
              </button>
              <button 
                onClick={() => onDelete(draft.id)}
                className="px-3 py-1.5 text-slate-600 hover:text-red-600 border border-slate-300 rounded hover:bg-slate-50 text-xs font-medium transition-colors"
              >
                Discard
              </button>
             </div>
          )}

          {draft.status === 'scheduled' && (
             <div className="text-xs text-purple-600 font-medium flex items-center gap-1 w-full justify-center bg-purple-50 py-1.5 rounded border border-purple-100">
               <Clock className="w-3.5 h-3.5" />
               Scheduled for {draft.scheduled_for ? new Date(draft.scheduled_for).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : 'Future'}
             </div>
          )}

           {draft.status === 'published' && (
             <div className="text-xs text-blue-600 font-medium flex items-center gap-1 w-full justify-center bg-blue-50 py-1.5 rounded border border-blue-100">
               <Send className="w-3.5 h-3.5" />
               Live on LinkedIn
             </div>
          )}
        </div>

        {draft.status === 'draft' && (
           <button className="text-xs text-slate-400 hover:text-blue-600 flex items-center gap-1 ml-2 opacity-0 group-hover:opacity-100 transition-opacity">
             <Edit3 className="w-3.5 h-3.5" />
           </button>
        )}
      </div>
    </div>
  );
};

