import React, { useState } from 'react';
import { Draft } from '../types';
import { ChevronLeft, ChevronRight, Clock, Calendar as CalendarIcon, ExternalLink } from 'lucide-react';

interface CalendarViewProps {
  drafts: Draft[];
  onDraftClick: (draft: Draft) => void;
}

const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

const CalendarView: React.FC<CalendarViewProps> = ({ drafts, onDraftClick }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

  const daysInMonth = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const firstDay = getFirstDayOfMonth(currentDate.getFullYear(), currentDate.getMonth());

  const days = [];
  for (let i = 0; i < firstDay; i++) days.push(null);
  for (let i = 1; i <= daysInMonth; i++) days.push(i);

  const handlePrevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  const handleNextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

  const getDraftsForDay = (day: number) => {
    return drafts.filter(d => {
      const date = d.scheduled_for ? new Date(d.scheduled_for) : (d.published_at ? new Date(d.published_at) : null);
      if (!date) return false;
      return date.getDate() === day && 
             date.getMonth() === currentDate.getMonth() && 
             date.getFullYear() === currentDate.getFullYear();
    });
  };

  const isToday = (day: number) => {
    const today = new Date();
    return day === today.getDate() &&
           currentDate.getMonth() === today.getMonth() &&
           currentDate.getFullYear() === today.getFullYear();
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden flex flex-col h-full min-h-[600px]">
      <div className="p-5 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
        <div className="flex items-center gap-3">
          <CalendarIcon className="w-5 h-5 text-blue-600" />
          <h3 className="font-bold text-slate-900">
            {MONTH_NAMES[currentDate.getMonth()]} {currentDate.getFullYear()}
          </h3>
        </div>
        <div className="flex gap-2">
          <button onClick={handlePrevMonth} className="p-2 hover:bg-slate-200 rounded-lg text-slate-600 transition-all">
            <ChevronLeft className="w-5 h-5" />
          </button>
          <button onClick={() => setCurrentDate(new Date())} className="px-3 py-1 text-xs font-bold text-slate-600 hover:text-slate-900 border border-slate-200 rounded-lg hover:bg-slate-50">
            Today
          </button>
          <button onClick={handleNextMonth} className="p-2 hover:bg-slate-200 rounded-lg text-slate-600 transition-all">
            <ChevronRight className="w-5 h-5" />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-7 border-b border-slate-100">
        {DAYS.map(day => (
          <div key={day} className="py-3 text-center text-[10px] font-bold text-slate-400 uppercase tracking-widest border-r border-slate-50 last:border-0">
            {day}
          </div>
        ))}
      </div>

      <div className="flex-1 grid grid-cols-7 auto-rows-fr">
        {days.map((day, index) => {
          const dayDrafts = day ? getDraftsForDay(day) : [];
          return (
            <div 
              key={index} 
              className={`min-h-[100px] border-r border-b border-slate-100 p-2 last:border-r-0 flex flex-col gap-1
                ${day === null ? 'bg-slate-50/30' : 'bg-white'}
                ${day && isToday(day) ? 'bg-blue-50/30' : ''}`}
            >
              {day && (
                <span className={`text-xs font-bold mb-1 w-6 h-6 flex items-center justify-center rounded-full
                  ${isToday(day) ? 'bg-blue-600 text-white' : 'text-slate-400'}`}>
                  {day}
                </span>
              )}
              <div className="flex flex-col gap-1 overflow-y-auto max-h-32 scrollbar-hide">
                {dayDrafts.map(d => (
                  <button
                    key={d.id}
                    onClick={() => onDraftClick(d)}
                    className={`text-[10px] p-1.5 rounded border text-left flex flex-col gap-0.5 group transition-all
                      ${d.status === 'scheduled' ? 'bg-purple-50 border-purple-100 text-purple-700 hover:border-purple-300' : 
                        d.status === 'published' ? 'bg-blue-50 border-blue-100 text-blue-700 hover:border-blue-300' : 
                        'bg-slate-50 border-slate-100 text-slate-700 hover:border-slate-300'}`}
                  >
                    <div className="flex justify-between items-center">
                      <span className="font-bold flex items-center gap-1">
                        <Clock className="w-2.5 h-2.5" />
                        {d.scheduled_for ? new Date(d.scheduled_for).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : 
                         d.published_at ? new Date(d.published_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : 'TBD'}
                      </span>
                      <ExternalLink className="w-2 h-2 opacity-0 group-hover:opacity-100" />
                    </div>
                    <p className="line-clamp-2 leading-tight">{d.content}</p>
                  </button>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

