import React, { useState, useEffect, useCallback } from 'react';
import { GoogleGenAI } from "@google/genai";
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import DraftsView from './components/DraftsView';
import Settings from './components/Settings';
import ActivityFeed from './components/ActivityFeed';
import Toaster from './components/Toaster';
import { 
  CURRENT_USER, 
  INITIAL_DRAFTS, 
  INITIAL_SOURCES, 
  INITIAL_ACTIVITIES 
} from './constants';
import { Draft, Source, Activity, AppNotification, NotificationType } from './types';

// Storage keys
const STORAGE_KEYS = {
  DRAFTS: 'linkedqueue_drafts',
  SOURCES: 'linkedqueue_sources',
  ACTIVITIES: 'linkedqueue_activities'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  // Initialize state from LocalStorage or constants
  const [drafts, setDrafts] = useState<Draft[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.DRAFTS);
    return saved ? JSON.parse(saved) : INITIAL_DRAFTS;
  });

  const [sources, setSources] = useState<Source[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.SOURCES);
    return saved ? JSON.parse(saved) : INITIAL_SOURCES;
  });

  const [activities, setActivities] = useState<Activity[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.ACTIVITIES);
    return saved ? JSON.parse(saved) : INITIAL_ACTIVITIES;
  });

  const [isGenerating, setIsGenerating] = useState(false);

  // Persist state changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.DRAFTS, JSON.stringify(drafts));
  }, [drafts]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.SOURCES, JSON.stringify(sources));
  }, [sources]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.ACTIVITIES, JSON.stringify(activities));
  }, [activities]);

  // Helper to add notification
  const notify = useCallback((message: string, type: NotificationType = 'info') => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, message, type, created_at: new Date().toISOString() }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  }, []);

  const removeNotification = (id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  // Simulate polling for draft updates (e.g. status changes from cron jobs)
  useEffect(() => {
    const interval = setInterval(() => {
      setDrafts(prev => {
        let changed = false;
        const next = prev.map(d => {
          if (d.status === 'scheduled' && d.scheduled_for && new Date(d.scheduled_for) <= new Date()) {
            changed = true;
            notify(`Successfully published post: "${d.content.substring(0, 30)}..."`, 'success');
            return { ...d, status: 'published', published_at: new Date().toISOString() };
          }
          return d;
        });
        return changed ? next : prev;
      });
    }, 10000); 

    return () => clearInterval(interval);
  }, [notify]);

  const handleToggleSource = (id: string) => {
    setSources(prev => prev.map(s => {
      if (s.id === id) {
        const newStatus = s.status === 'connected' ? 'disconnected' : 'connected';
        notify(`${s.provider} ${newStatus === 'connected' ? 'connected' : 'disconnected'}`, newStatus === 'connected' ? 'success' : 'info');
        return { ...s, status: newStatus };
      }
      return s;
    }));
  };

  const handleGenerateDraft = async (prompt?: string, activityId?: string) => {
    setIsGenerating(true);
    try {
      const apiKey = process.env.API_KEY || '';
      const activity = activityId ? activities.find(a => a.id === activityId) : null;

      let content = "";
      let confidence = 0.85;

      if (apiKey) {
        const ai = new GoogleGenAI({ apiKey });
        const systemPrompt = `You are a professional LinkedIn content creator. Write a post that is high-impact, uses 1-2 relevant emojis, and fits a "humble builder" narrative. Stay under 400 characters. 
          Context: ${prompt || "Building an automated publishing platform"}`;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: systemPrompt,
        });
        content = response.text || "Failed to generate content.";
        confidence = 0.96;
      } else {
        await new Promise(resolve => setTimeout(resolve, 1500));
        const topics = [
          "Building software in public means being honest about the bugs as much as the features. 🛠️ #BuildInPublic #SaaS",
          "Just realized how critical proper indexing is for scale. 🚀 Optimized our sync service and dropped latency by 40%! #Engineering #Performance",
          "One of the best ways to learn is by automating your own manual workflows. Content creation is next. 💡 #Automation #LinkedIn"
        ];
        content = topics[Math.floor(Math.random() * topics.length)];
      }

      const newDraft: Draft = {
        id: `d-${Date.now()}`,
        content: content.trim(),
        status: 'draft',
        style: 'humble_builder',
        confidence_score: confidence,
        created_at: new Date().toISOString(),
        activity_summary: activity ? activity.summary : (prompt ? "Manual Prompt" : "AI Ingestion")
      };

      setDrafts(prev => [newDraft, ...prev]);
      notify("New AI draft generated and ready for review", "success");
      setActiveTab('drafts');
    } catch (error) {
      console.error("Generation failed", error);
      notify("Draft generation failed. Please check connection.", "error");
    } finally {
      setIsGenerating(false);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard drafts={drafts} sources={sources} activities={activities} />;
      case 'drafts':
        return (
          <DraftsView 
            drafts={drafts} 
            setDrafts={setDrafts} 
            activities={activities}
            onGenerate={handleGenerateDraft}
            isGenerating={isGenerating}
          />
        );
      case 'activity':
        return <ActivityFeed activities={activities} />;
      case 'settings':
        return <Settings user={CURRENT_USER} sources={sources} onToggleSource={handleToggleSource} />;
      default:
        return <Dashboard drafts={drafts} sources={sources} activities={activities} />;
    }
  };

  return (
    <Layout user={CURRENT_USER} activeTab={activeTab} onTabChange={setActiveTab}>
      <Toaster notifications={notifications} onRemove={removeNotification} />
      <div className="max-w-7xl mx-auto">
        {renderContent()}
      </div>
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { Draft } from '../types';
import { 
  Calendar, 
  Send, 
  Edit3, 
  Trash2, 
  CheckCircle, 
  Clock, 
  AlertCircle,
  ThumbsUp,
  Github,
  RefreshCcw,
  Loader2,
  XCircle
} from 'lucide-react';

interface DraftCardProps {
  draft: Draft;
  onStatusChange: (id: string, status: Draft['status']) => void;
  onDelete: (id: string) => void;
}

const DraftCard: React.FC<DraftCardProps> = ({ draft, onStatusChange, onDelete }) => {
  const [isPublishing, setIsPublishing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const handlePublish = async () => {
    setIsPublishing(true);
    setErrorMessage(null);

    // Simulate network request
    await new Promise(resolve => setTimeout(resolve, 1500));

    // Simulate random failure (20% chance) to demonstrate retry logic
    const fail = Math.random() < 0.20;

    if (fail) {
      onStatusChange(draft.id, 'failed');
      setErrorMessage("Network timeout. Connection to LinkedIn API failed.");
    } else {
      onStatusChange(draft.id, 'published');
      setErrorMessage(null);
    }
    setIsPublishing(false);
  };

  const getStatusColor = (status: Draft['status']) => {
    switch (status) {
      case 'approved': return 'bg-green-100 text-green-700 border-green-200';
      case 'published': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'scheduled': return 'bg-purple-100 text-purple-700 border-purple-200';
      case 'draft': return 'bg-amber-100 text-amber-700 border-amber-200';
      case 'failed': return 'bg-red-100 text-red-700 border-red-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const getStatusIcon = (status: Draft['status']) => {
    switch (status) {
      case 'approved': return <CheckCircle className="w-4 h-4" />;
      case 'published': return <Send className="w-4 h-4" />;
      case 'scheduled': return <Clock className="w-4 h-4" />;
      case 'failed': return <AlertCircle className="w-4 h-4" />;
      default: return <Edit3 className="w-4 h-4" />;
    }
  };

  return (
    <div className="bg-white rounded-2xl border border-slate-200 shadow-sm hover:shadow-lg transition-all duration-300 flex flex-col h-full group overflow-hidden">
      <div className="p-5 flex-1 relative">
        <div className="flex justify-between items-start mb-4">
          <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider border ${getStatusColor(draft.status)}`}>
            {getStatusIcon(draft.status)}
            <span>{draft.status}</span>
          </div>
          <div className="flex items-center gap-1.5 text-[10px] font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded-lg">
            <Sparkles className="w-3 h-3 text-purple-500" />
            <span>{Math.round(draft.confidence_score * 100)}% Match</span>
          </div>
        </div>

        {draft.activity_summary && (
          <div className="flex items-center gap-2 mb-4 text-[10px] font-bold text-slate-500 bg-slate-50/50 p-2.5 rounded-xl border border-slate-100">
            <Github className="w-3.5 h-3.5 text-slate-400" />
            <span className="truncate">{draft.activity_summary}</span>
          </div>
        )}

        <p className="text-slate-800 text-sm leading-relaxed whitespace-pre-wrap font-medium">
          {draft.content}
        </p>

        {errorMessage && draft.status === 'failed' && (
          <div className="mt-4 p-3 bg-red-50 border border-red-100 rounded-xl text-xs text-red-600 flex items-start gap-2.5">
            <XCircle className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <span className="font-semibold">{errorMessage}</span>
          </div>
        )}
      </div>

      <div className="border-t border-slate-100 p-4 bg-slate-50/30 rounded-b-2xl flex justify-between items-center">
        <div className="flex gap-2 w-full">
          {draft.status === 'draft' && (
            <>
              <button 
                onClick={() => onStatusChange(draft.id, 'approved')}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-green-600 text-white text-xs font-bold rounded-xl hover:bg-green-700 transition-all active:scale-95 shadow-sm shadow-green-100"
              >
                <ThumbsUp className="w-3.5 h-3.5" />
                Approve
              </button>
              <button 
                onClick={() => onDelete(draft.id)}
                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                title="Reject"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </>
          )}

          {draft.status === 'approved' && (
            <>
              <button 
                onClick={handlePublish}
                disabled={isPublishing}
                className="flex-[2] flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white text-xs font-bold rounded-xl hover:bg-blue-700 transition-all disabled:opacity-50 min-w-[120px] shadow-sm shadow-blue-100 active:scale-95"
              >
                {isPublishing ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" />
                    <span>Publishing...</span>
                  </>
                ) : (
                  <>
                    <Send className="w-4 h-4" />
                    <span>Post Now</span>
                  </>
                )}
              </button>
              <button 
                onClick={() => onStatusChange(draft.id, 'scheduled')}
                disabled={isPublishing}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 text-xs font-bold rounded-xl hover:bg-slate-50 transition-all"
              >
                <Calendar className="w-3.5 h-3.5" />
                Schedule
              </button>
            </>
          )}

          {draft.status === 'failed' && (
             <div className="flex items-center gap-2 w-full">
               <button 
                onClick={handlePublish}
                disabled={isPublishing}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-red-600 text-white text-xs font-bold rounded-xl hover:bg-red-700 transition-all disabled:opacity-70 shadow-lg shadow-red-200"
              >
                {isPublishing ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCcw className="w-4 h-4" />}
                Retry Now
              </button>
              <button 
                onClick={() => onDelete(draft.id)}
                className="px-4 py-2 text-slate-600 hover:text-red-600 border border-slate-200 rounded-xl hover:bg-white text-xs font-bold transition-all"
              >
                Discard
              </button>
             </div>
          )}

          {draft.status === 'scheduled' && (
             <div className="text-[10px] text-purple-600 font-bold flex items-center gap-1.5 w-full justify-center bg-purple-50 py-2.5 rounded-xl border border-purple-100 uppercase tracking-wider">
               <Clock className="w-3.5 h-3.5" />
               Scheduled: {draft.scheduled_for ? new Date(draft.scheduled_for).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) : 'Future'}
             </div>
          )}

           {draft.status === 'published' && (
             <div className="text-[10px] text-blue-600 font-bold flex items-center gap-1.5 w-full justify-center bg-blue-50 py-2.5 rounded-xl border border-blue-100 uppercase tracking-wider">
               <Send className="w-3.5 h-3.5" />
               Published to LinkedIn
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

