import React, { useState, useEffect, useCallback } from 'react';
import { GoogleGenAI } from "@google/genai";
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import DraftsView from './components/DraftsView';
import Settings from './components/Settings';
import ActivityFeed from './components/ActivityFeed';
import Toaster from './components/Toaster';
import { 
  CURRENT_USER, 
  INITIAL_DRAFTS, 
  INITIAL_SOURCES, 
  INITIAL_ACTIVITIES 
} from './constants';
import { Draft, Source, Activity, AppNotification, NotificationType, DraftStatus } from './types';

// Storage keys
const STORAGE_KEYS = {
  DRAFTS: 'linkedqueue_drafts',
  SOURCES: 'linkedqueue_sources',
  ACTIVITIES: 'linkedqueue_activities'
};

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);

  // Initialize state from LocalStorage or constants
  const [drafts, setDrafts] = useState<Draft[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.DRAFTS);
    return saved ? JSON.parse(saved) : INITIAL_DRAFTS;
  });

  const [sources, setSources] = useState<Source[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.SOURCES);
    return saved ? JSON.parse(saved) : INITIAL_SOURCES;
  });

  const [activities, setActivities] = useState<Activity[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.ACTIVITIES);
    return saved ? JSON.parse(saved) : INITIAL_ACTIVITIES;
  });

  const [isGenerating, setIsGenerating] = useState(false);

  // Persist state changes
  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.DRAFTS, JSON.stringify(drafts));
  }, [drafts]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.SOURCES, JSON.stringify(sources));
  }, [sources]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEYS.ACTIVITIES, JSON.stringify(activities));
  }, [activities]);

  // Helper to add notification
  const notify = useCallback((message: string, type: NotificationType = 'info') => {
    const id = Date.now().toString();
    setNotifications(prev => [...prev, { id, message, type, created_at: new Date().toISOString() }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  }, []);

  const removeNotification = (id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  // Simulate polling for draft updates (e.g. status changes from cron jobs)
  useEffect(() => {
    const interval = setInterval(() => {
      setDrafts(prev => {
        let changed = false;
        const next = prev.map((d): Draft => {
          if (d.status === 'scheduled' && d.scheduled_for && new Date(d.scheduled_for) <= new Date()) {
            changed = true;
            notify(`Successfully published post: "${d.content.substring(0, 30)}..."`, 'success');
            // Fixed type error by explicitly typing the map and using DraftStatus cast
            return { 
              ...d, 
              status: 'published' as DraftStatus, 
              published_at: new Date().toISOString() 
            };
          }
          return d;
        });
        return changed ? next : prev;
      });
    }, 10000); 

    return () => clearInterval(interval);
  }, [notify]);

  const handleToggleSource = (id: string) => {
    setSources(prev => prev.map(s => {
      if (s.id === id) {
        const newStatus = s.status === 'connected' ? 'disconnected' : 'connected';
        notify(`${s.provider} ${newStatus === 'connected' ? 'connected' : 'disconnected'}`, newStatus === 'connected' ? 'success' : 'info');
        return { ...s, status: newStatus };
      }
      return s;
    }));
  };

  const handleGenerateDraft = async (prompt?: string, activityId?: string) => {
    setIsGenerating(true);
    try {
      // Use API Key directly as per guidelines
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
      const activity = activityId ? activities.find(a => a.id === activityId) : null;

      const contextPrompt = prompt || "Building an automated publishing platform";

      // strictly follow Gemini API guidelines: use ai.models.generateContent and .text property
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate a LinkedIn post based on this context: ${contextPrompt}`,
        config: {
          systemInstruction: 'You are a professional LinkedIn content creator. Write a post that is high-impact, uses 1-2 relevant emojis, and fits a "humble builder" narrative. Stay under 400 characters.',
        }
      });

      const content = response.text || "Failed to generate content.";
      const confidence = 0.96;

      const newDraft: Draft = {
        id: `d-${Date.now()}`,
        content: content.trim(),
        status: 'draft',
        style: 'humble_builder',
        confidence_score: confidence,
        created_at: new Date().toISOString(),
        activity_summary: activity ? activity.summary : (prompt ? "Manual Prompt" : "AI Ingestion")
      };

      setDrafts(prev => [newDraft, ...prev]);
      notify("New AI draft generated and ready for review", "success");
      setActiveTab('drafts');
    } catch (error) {
      console.error("Generation failed", error);
      notify("Draft generation failed. Please check connection.", "error");
    } finally {
      setIsGenerating(false);
    }
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard drafts={drafts} sources={sources} activities={activities} />;
      case 'drafts':
        return (
          <DraftsView 
            drafts={drafts} 
            setDrafts={setDrafts} 
            activities={activities}
            onGenerate={handleGenerateDraft}
            isGenerating={isGenerating}
          />
        );
      case 'activity':
        return <ActivityFeed activities={activities} />;
      case 'settings':
        return <Settings user={CURRENT_USER} sources={sources} onToggleSource={handleToggleSource} />;
      default:
        return <Dashboard drafts={drafts} sources={sources} activities={activities} />;
    }
  };

  return (
    <Layout user={CURRENT_USER} activeTab={activeTab} onTabChange={setActiveTab}>
      <Toaster notifications={notifications} onRemove={removeNotification} />
      <div className="max-w-7xl mx-auto">
        {renderContent()}
      </div>
    </Layout>
  );
};

export default App;

